select 'produtos' k, md5(coalesce(string_agg(to_jsonb(p)::text, '|' order by p.id),'')) v from produtos p where p.id in ('27c229d7-f192-41eb-aad1-0c69ece53eba','a027ac97-ffd1-4834-8ed0-d3a94aac4aee')
union all select 'roteiro_etapas_legado', md5(coalesce(string_agg(to_jsonb(e)::text, '|' order by e.id),'')) from roteiro_etapas e where e.produto_id in ('27c229d7-f192-41eb-aad1-0c69ece53eba','a027ac97-ffd1-4834-8ed0-d3a94aac4aee')
union all select 'roteiro_etapa_maquinas_legado', md5(coalesce(string_agg(to_jsonb(m)::text, '|' order by m.etapa_id, m.maquina_id),'')) from roteiro_etapa_maquinas m join roteiro_etapas e on e.id=m.etapa_id where e.produto_id in ('27c229d7-f192-41eb-aad1-0c69ece53eba','a027ac97-ffd1-4834-8ed0-d3a94aac4aee')
union all select 'previsao_itens_26_10', md5(coalesce(string_agg(to_jsonb(i)::text, '|' order by i.id),'')) from previsao_itens i join previsoes p on p.id=i.previsao_id where p.semana_inicio='2026-10-26'
union all select 'previsao_item_maquinas_26_10', md5(coalesce(string_agg(to_jsonb(m)::text, '|' order by m.item_id, m.etapa_id, m.maquina_id),'')) from previsao_item_maquinas m join previsao_itens i on i.id=m.item_id join previsoes p on p.id=i.previsao_id where p.semana_inicio='2026-10-26'
union all select 'previsao_item_adicional_26_10', md5(coalesce(string_agg(to_jsonb(a)::text, '|' order by a.item_id, a.etapa_id),'')) from previsao_item_adicional_etapa a join previsao_itens i on i.id=a.item_id join previsoes p on p.id=i.previsao_id where p.semana_inicio='2026-10-26'
union all select 'previsao_dias_equipe_26_10', md5(coalesce((select string_agg(to_jsonb(d)::text, '|' order by d.dia) from previsao_dias_produtivos d join previsoes p on p.id=d.previsao_id where p.semana_inicio='2026-10-26'),'') || coalesce((select string_agg(to_jsonb(e)::text, '|' order by e.funcionario_id) from previsao_equipe_semana e join previsoes p on p.id=e.previsao_id where p.semana_inicio='2026-10-26'),''))
union all select 'escala_dias_26_10', md5(coalesce(string_agg(to_jsonb(d)::text, '|' order by d.data),'')) from escala_producao_dias d join previsoes p on p.id=d.previsao_id where p.semana_inicio='2026-10-26'
union all select 'escala_alocacoes_26_10', md5(coalesce(string_agg(a.data||a.periodo_id||a.funcionario_id::text||coalesce(a.maquina_id::text,'')||coalesce(a.produto_id::text,'')||coalesce(a.etapa_id::text,'')||a.pecas::text||coalesce(a.pecas_adicional,0)::text||a.origem||a.excecao_revezamento::text, '|' order by a.data,a.periodo_id,a.funcionario_id),'')) from escala_producao_alocacoes a where a.data between '2026-10-26' and '2026-11-01'
union all select 'escala_plano_entrada_26_10', md5((select public.escala_plano_entrada(id)::text from previsoes where semana_inicio='2026-10-26'))
union all select 'previsoes_sem_coluna_nova', md5(string_agg(to_jsonb(p)::text, '|' order by p.id)) from (select id, semana_inicio, created_at, updated_at from previsoes) p
union all select 'apontamentos_26_10', md5(coalesce(string_agg(to_jsonb(a)::text, '|' order by a.id),'')) from apontamentos_producao a where a.data between '2026-10-26' and '2026-11-01'
union all select 'escala_parametros', md5(coalesce(string_agg(chave||valor::text, '|' order by chave),'')) from escala_parametros
union all select 'tabelas_antigas_colunas', md5(string_agg(c.relname||'.'||a.attname||':'||format_type(a.atttypid,a.atttypmod), '|' order by c.relname, a.attnum)) from pg_class c join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped where c.relnamespace='public'::regnamespace and c.relkind='r' and c.relname not in ('produto_rota','rota_etapas','produto_pool_comum','previsao_rota_limite','escala_rota_divisao','produto_variante_legada', 'rotas_config', 'rotas_planejador_sombra') and not (c.relname='previsoes' and a.attname='modelo_rotas');
